// Records every byte that Hash feeds to a Hasher.
struct Recorder(Vec<u8>);
impl Hasher for Recorder {
    fn write(&mut self, bytes: &[u8]) { self.0.extend_from_slice(bytes); }
    fn finish(&self) -> u64 { 0 }
}

